/* wall_dev.c (Local, L1544): the deviation automaton on a periodic strip. State at a row: phase, first difference D from the strip, and the m cells of y below D. One tick back: y'(k) = y(k+3) ^ (y(k+4) | y(k+5)).
   Mode fair: unknown cells fair; arrival distribution from sampled exits. Mode free: unknown cells free; longest path to the wall by value iteration, rows in the lock excluded.
   Usage: ./wall_dev CYCFILE SETFILE M MODE [N SEED]. CYCFILE: one word per phase in backward-tick order (low to high). */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef unsigned char u8; typedef unsigned long long u64; typedef unsigned int u32;
#define MAXK 200
static int P,K,M,Dn; static u8 X[8][MAXK+8]; static char S[64][260]; static int nS; static u8 UW[64][MAXK+8];
static u64 rs; static inline u64 rnd(void){ rs^=rs<<13; rs^=rs>>7; rs^=rs<<17; return rs; }
static inline long idx(int ph,int D,u32 w){ return (((long)ph*Dn+(D-11))<<M)|w; }
/* y cell at offset j for state (ph,D,w) */
static inline int ycell(int ph,int D,u32 w,int j){ if(j<D) return X[ph][j]; if(j==D) return !X[ph][D]; return (w>>(j-D-1))&1; }
static int inU(int ph,int D,u32 w){ if(D+M<K-1) return 0; for(int u=0;u<nS;u++){ int eq=1; for(int k=0;k<K;k++) if(ycell(ph,D,w,k)!=UW[u][k]){ eq=0; break; } if(eq) return 1; } return 0; }
/* one tick back. returns 0: arrival; 1: first difference found, *nd, *pre (known cells below it), *kn known count; 2: agreement through known range, *nd = first offset not known; 3: agreement through the whole window (row in the strip window) */
static inline int stepst(int ph,int D,u32 w,int*nd,u32*pre,int*kn){ int p2=(ph+P-1)%P; int kend=D+M-5; int lo=D-5; if(lo<0) lo=0; int found=-1; int cells[MAXK+40]; for(int k=lo;k<=kend;k++){ int v=ycell(ph,D,w,k+3)^(ycell(ph,D,w,k+4)|ycell(ph,D,w,k+5)); cells[k-lo]=v; if(found<0&&k<K&&v!=X[p2][k]) found=k; } if(found>=0){ if(found<=10) return 0; *nd=found; u32 b=0; int c=0; for(int k=found+1;k<=kend&&c<M;k++){ b|=(u32)cells[k-lo]<<c; c++; } *pre=b; *kn=c; return 1; } if(kend>=K-1) return 3; *nd=kend+1; return 2; }
int main(int c,char**a){ char line[300]; FILE*f=fopen(a[1],"r"); while(fgets(line,300,f)){ int n=strcspn(line,"\n"); line[n]=0; if(!n) continue; K=n; for(int k=0;k<n;k++) X[P][k]=line[n-1-k]=='#'; P++; } fclose(f); f=fopen(a[2],"r"); while(fgets(line,300,f)){ int n=strcspn(line,"\n"); line[n]=0; if(!n) continue; strcpy(S[nS],line); for(int k=0;k<n;k++) UW[nS][k]=line[n-1-k]=='#'; nS++; } fclose(f); M=atoi(a[3]); int fair=!strcmp(a[4],"fair"); Dn=K-11; long NS=(long)P*Dn<<M;
  if(!fair){ /* free: value iteration, L = ticks to arrival from this row; -1 invalid */ int*L=malloc(sizeof(int)*NS),*L2=malloc(sizeof(int)*NS); u8*bad=calloc(NS,1); for(int ph=0;ph<P;ph++) for(int D=11;D<K;D++) for(u32 w=0;w<(1u<<M);w++){ long i=idx(ph,D,w); L[i]=0; bad[i]=inU(ph,D,w); }
    int maxrounds=c>5?atoi(a[5]):400; int best=0,rounds=0; for(int r=1;r<=maxrounds;r++){ long changed=0; best=0; for(int ph=0;ph<P;ph++){ int p2=(ph+P-1)%P; for(int D=11;D<K;D++){ for(u32 w=0;w<(1u<<M);w++){ long i=idx(ph,D,w); if(bad[i]){ L2[i]=0; continue; } int nd,kn; u32 pre; int t=stepst(ph,D,w,&nd,&pre,&kn); int v; if(t==0) v=1; else if(t==3) v=1; else if(t==1){ int extra=M-kn; int mx=0; for(u32 e=0;e<(1u<<extra);e++){ u32 w2=pre|(e<<kn); long j=idx(p2,nd,w2); if(!bad[j]&&L[j]>mx) mx=L[j]; } v=1+mx; } else { int mx=0; for(int d2=nd;d2<K;d2++) for(u32 w2=0;w2<(1u<<M);w2++){ long j=idx(p2,d2,w2); if(!bad[j]&&L[j]>mx) mx=L[j]; } v=1+mx; } L2[i]=v; if(v!=L[i]) changed++; if(v>best) best=v; } } } int*tmp=L; L=L2; L2=tmp; rounds=r; if(!changed) break; if(r%10==0){ printf("round %d: longest %d, changed %ld\n",r,best,changed); fflush(stdout); } }
    printf("free graph: m %d rounds %d longest path to the wall from any state outside the lock: %d ticks%s\n",M,rounds,best,rounds>=maxrounds?" (NOT CONVERGED: a cycle)":""); if(rounds>=maxrounds){ long shown=0; for(int ph=0;ph<P;ph++) for(int D=11;D<K;D++) for(u32 w=0;w<(1u<<M);w++){ long i=idx(ph,D,w); if(!bad[i]&&L[i]>=best-1&&shown<24){ printf("  ph %d D %d w ",ph,D); for(int b=0;b<M;b++) putchar((w>>b)&1?'#':'.'); printf(" L %d\n",L[i]); shown++; } } } return 0; }
  /* fair: start from sampled exits */ long N=atol(a[5]); rs=strtoull(a[6],0,10)*2654435761ULL+88172645463325252ULL; for(int i=0;i<20;i++) rnd(); double*p=calloc(NS,sizeof(double)),*q=calloc(NS,sizeof(double)); double mass=0; static double arr[400]; long kept=0; int row0=1; for(long it=0;it<N;it++){ int u=rnd()%nS; static u8 y0[MAXK+64],y1[MAXK+64]; int top=K+40; for(int k=0;k<K;k++) y0[k]=UW[u][k]; for(int k=K;k<top;k++) y0[k]=rnd()>>63; int nk=top-5; for(int k=0;k<nk;k++) y1[k]=y0[k+3]^(y0[k+4]|y0[k+5]); int isU=0; for(int r=0;r<nS&&!isU;r++){ int eq=1; for(int k=0;k<K;k++) if(y1[k]!=UW[r][k]){ eq=0; break; } if(eq) isU=1; } if(isU) continue; /* phase of y_1: the strip row with the deepest agreement */ int bp=0,bd=-1; for(int ph=0;ph<P;ph++){ int d=0; while(d<K&&y1[d]==X[ph][d]) d++; if(d>bd){ bd=d; bp=ph; } } if(bd>=K||bd<=10) continue; u32 w=0; for(int i=0;i<M;i++) w|=(u32)y1[bd+1+i]<<i; p[idx(bp,bd,w)]+=1; kept++; mass+=1; }
  printf("sampled exits %ld\n",kept); for(long i=0;i<NS;i++) p[i]/=mass; double alive=1; int T=c>7?atoi(a[7]):120; double meanA=0; for(int s=1;s<=T;s++){ memset(q,0,sizeof(double)*NS); static double resetm[8][MAXK+8]; memset(resetm,0,sizeof resetm); double arrived=0,lost=0; for(int ph=0;ph<P;ph++){ int p2=(ph+P-1)%P; for(int D=11;D<K;D++){ for(u32 w=0;w<(1u<<M);w++){ long i=idx(ph,D,w); double v=p[i]; if(v==0) continue; int nd,kn; u32 pre; int t=stepst(ph,D,w,&nd,&pre,&kn); if(t==0) arrived+=v; else if(t==3) lost+=v; else if(t==1){ int extra=M-kn; double vv=v/(double)(1u<<extra); for(u32 e=0;e<(1u<<extra);e++) q[idx(p2,nd,pre|(e<<kn))]+=vv; } else { double r=v; for(int d2=nd;d2<K-1;d2++){ r/=2; resetm[p2][d2]+=r; } resetm[p2][K-1]+=r; } } } } for(int ph=0;ph<P;ph++) for(int D=11;D<K;D++) if(resetm[ph][D]>0){ double vv=resetm[ph][D]/(double)(1u<<M); for(u32 w=0;w<(1u<<M);w++) q[idx(ph,D,w)]+=vv; } double*tmp=p; p=q; q=tmp; arr[s+1]=arrived; { double tot=0; for(long i=0;i<NS;i++) tot+=p[i]; alive=tot; } meanA+=(s+1)*arrived; printf("row %d: arrive %.4e lost %.2e alive %.4e ratio %.4f\n",s+1,arrived,lost,alive,alive>0?alive/(alive+arrived+lost):0.0); if(alive<1e-40) break; }
  printf("mean arrival row %.3f\n",meanA); return 0; }
